import{_ as i,l as o,o as e,c as l,v as t,p as n,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"AES 结构","description":"","frontmatter":{"title":"AES 结构","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aes-structure.md","filePath":"cs/aes-structure.md","lastUpdated":1789023840000}'),p={name:"cs/aes-structure.md"};function S(u,a,m,E,A,_){const s=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="aes-结构" tabindex="-1">AES 结构 <a class="header-anchor" href="#aes-结构" aria-label="Permalink to &quot;AES 结构&quot;">​</a></h1><div class="epigraph"><p>AES 是 128 比特块上的代换–置换网络：字节代换、行移位、列混合、加轮密钥。它是候选伪随机置换，不是一次一密，也不是「公开算法就不安全」。</p><footer>—— Daemen and Rijmen, The Design of Rijndael；NIST FIPS 197</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/prg-prf">PRG 与 PRF</a>给出计算安全的函数合同。缺口是<strong>实践里那张置换表从哪来</strong>。主干<a href="/cs/symmetric-crypto">对称加密</a>已用 AES 当名字；本课只补结构：SPN、圈数与密钥宽，不把侧信道当本课主轴。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PRF 课留下「候选」。Rijndael 被定为 AES：状态 4×4 字节，SubBytes 用有限域逆，ShiftRows 扩散位置，MixColumns 在 $ \\mathrm{GF}(2^8) $ 上混列，AddRoundKey 异或轮密钥。缺口是理解为何这是 SPN 而不是 Feistel——后课才对照 DES。不要把圈数口算成「安全比特」。</p><h3 id="公开算法" tabindex="-1">公开算法 <a class="header-anchor" href="#公开算法" aria-label="Permalink to &quot;公开算法&quot;">​</a></h3><p>Kerckhoffs：敌手知道算法。安全性在密钥。把 AES 当「军用机密算法」是倒退。</p><p><span class="marginnote">FIPS 197。宽 128/192/256 只改圈数与密钥扩展，块仍是 128。本课不写差分/线性分析的操作程序，只承认设计对着这些分析留余量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按一圈的四步走一遍数据路径。密钥扩展把主密钥变成轮密钥。强调：AES 本身只处理一块；消息长度、完整性、nonce 是<a href="/cs/block-modes">分组模式</a>的合同，本课不重写 GCM。</p>',12)),(e(),n(c,null,{default:r(()=>[h(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22128%20%E6%AF%94%E7%89%B9%E5%9D%97%22%5D%20--%3E%20SB%5B%22SubBytes%22%5D%0A%20%20SB%20--%3E%20SR%5B%22ShiftRows%22%5D%0A%20%20SR%20--%3E%20MC%5B%22MixColumns%22%5D%0A%20%20MC%20--%3E%20ARK%5B%22AddRoundKey%22%5D%0A%20%20ARK%20--%3E%20OUT%5B%22%E4%B8%8B%E4%B8%80%E5%9C%88%E6%88%96%E5%AF%86%E6%96%87%E5%9D%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代换提供非线性，置换与列混合提供扩散，轮密钥打断对称。作为 PRP 候选，它被模式调用：ECB 仍会泄漏相等块——那是模式的锅，不是圈函数「弱了」。实现必须防缓存定时，那是侧信道课的缺口，结构课只点名。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲如何差分分析，不列全部 S 盒代数式当作业。下一课用 Feistel 对照：DES 把块劈成两半，AES 则是 SPN。后课默认：提到分组密码结构，AES 指 FIPS 197 的 SPN。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PRG/PRF 要候选；AES 是 128 比特 SPN。</li><li>圈函数：代换、移位、列混、加轮密钥。</li><li>块密码≠模式；完整性仍在 AEAD。</li><li>Feistel/DES 是下一课的结构对照。</li><li>出处：Daemen and Rijmen, <em>The Design of Rijndael</em>；NIST FIPS 197。</li></ul>',8))])}const R=i(p,[["render",S]]);export{P as __pageData,R as default};
